{
  "interpretation": {
    "name": "Line1NutrunnerTighteningWithReturn",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring the shared nutrunner NR7 to station st1, tighten the F25 fasteners with the MES program, evaluate and record the result, then return the tool to the crib.",
    "constraints": [
      "Reserve NR7 before any use; every tool-using Step depends on reserve-tool (lease renewal)",
      "transport-tool is delegated to the Executor agvexecutor",
      "NR7 must be at the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program; no torque or tolerance literals in the Recipe",
      "The tightening must be evaluated and recorded",
      "The tool must be returned to the crib and the reservation released afterwards"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "one-off, for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tighten-f25",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "MoveToStation",
        "steps": [
          {"name": "reserve-nr7", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "fetch-program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "MoveToStation",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Verify",
        "steps": [
          {"name": "configure-nr7", "service": "configure-tool", "next": ["tighten-nr7"], "dep": ["reserve-nr7", "fetch-program", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten-nr7", "service": "tighten-fasteners", "next": [], "dep": ["reserve-nr7", "configure-nr7", "transport-to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Verify",
        "next": "ReturnTool",
        "steps": [
          {"name": "evaluate-result", "service": "evaluate-tightening", "next": [], "dep": ["tighten-nr7", "fetch-program"], "executor": null, "params": {}},
          {"name": "record-result", "service": "record-tightening", "next": [], "dep": ["tighten-nr7"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "ReturnTool",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release-nr7"], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve-nr7"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
